"""Compare panel aggregation rules on the pooled replies of the four pre-panel runs."""
import sys, random, difflib, collections
sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
sys.path.insert(0, "/tmp/analysis")
from pool import build, TASKS
from answer_space import (answers_agree, answer_text, ground_reply, load_answer_space,
                          strip_annotation)
from benchmark.data.evaluators import get_evaluator

SPACE = load_answer_space("/workspace/runs/13b8664bc78f4264c10a36e67028dfdb45cecde2/USPTO/memory.json")

def load_space(task):
    return load_answer_space(f"/workspace/runs/13b8664bc78f4264c10a36e67028dfdb45cecde2/{task}/memory.json")

def norm(text):
    return strip_annotation(text).strip().lower()

def sim(a, b):
    if a == b:
        return 1.0
    return difflib.SequenceMatcher(None, a, b).ratio()

def rule_mode(replies):
    keys = [norm(answer_text(r)) for r in replies]
    counts = collections.Counter(keys)
    leader = max(counts, key=lambda k: counts[k])
    return keys.index(leader)

def rule_medoid(replies):
    keys = [norm(answer_text(r)) for r in replies]
    best, best_score = 0, -1.0
    for i, key in enumerate(keys):
        score = sum(sim(key, other) for j, other in enumerate(keys) if j != i)
        if score > best_score:
            best, best_score = i, score
    return best

def rule_cluster(replies, threshold=0.8):
    keys = [norm(answer_text(r)) for r in replies]
    clusters = []
    for i, key in enumerate(keys):
        for cluster in clusters:
            if sim(key, keys[cluster[0]]) >= threshold:
                cluster.append(i)
                break
        else:
            clusters.append([i])
    # largest cluster, ties -> the one whose medoid is most central / earliest
    best = max(range(len(clusters)), key=lambda c: (len(clusters[c]), -min(clusters[c])))
    members = clusters[best]
    if len(members) == 1:
        return members[0]
    best_i, best_score = members[0], -1.0
    for i in members:
        score = sum(sim(keys[i], keys[j]) for j in members if j != i)
        if score > best_score:
            best_i, best_score = i, score
    return best_i

def evaluate(pool, rule, k=8, partitions=200, seed=7):
    rng = random.Random(seed)
    out = {}
    for task in TASKS:
        keys = [key for key in pool if key[0] == task and len(pool[key]) == 8]
        keys.sort()
        evaluator = get_evaluator(task)
        correct = total = 0
        for key in keys:
            items = list(pool[key].values())
            for _ in range(partitions):
                draws = rng.sample(items, k)
                replies = [ground_reply(d["reply"], SPACES[task]) for d in draws]
                target = items[0]["target"]
                pred = answer_text(replies[rule(replies)])
                total += 1
                correct += bool(evaluator(pred, target)["was_correct"] if isinstance(evaluator(pred, target), dict) else evaluator(pred, target))
        out[task] = correct / total if total else 0.0
    out["average"] = sum(out[t] for t in TASKS) / len(TASKS)
    return out

SPACES = {task: load_space(task) for task in TASKS}

if __name__ == "__main__":
    pool = build()
    print("single first draw:", evaluate(pool, lambda r: 0, partitions=200))
    print("mode   :", evaluate(pool, rule_mode))
    print("medoid :", evaluate(pool, rule_medoid))
    for th in (0.7, 0.8, 0.9, 0.95):
        print(f"cluster@{th}:", evaluate(pool, lambda r, t=th: rule_cluster(r, t)))
